"""Generate three polished PDF deliverables plus editable Markdown evidence."""
from pathlib import Path
import json,html
import pandas as pd
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak,Image,KeepTogether
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
R=Path(__file__).resolve().parents[1];P=R/'data/processed';O=R/'reports';O.mkdir(exist_ok=True)
M=json.loads((P/'metrics.json').read_text());D=pd.read_csv(P/'customers_features.csv')
NAVY=colors.HexColor('#12263f');TEAL=colors.HexColor('#166e75');LIGHT=colors.HexColor('#eef4f8')
S=getSampleStyleSheet()
S.add(ParagraphStyle(name='TitleCustom',fontName='Helvetica-Bold',fontSize=26,leading=30,textColor=NAVY,spaceAfter=16))
S.add(ParagraphStyle(name='Kicker',fontName='Helvetica-Bold',fontSize=9,leading=12,textColor=TEAL,spaceAfter=10))
S.add(ParagraphStyle(name='BodyCustom',fontName='Helvetica',fontSize=10,leading=14.5,textColor=NAVY,spaceAfter=9))
S.add(ParagraphStyle(name='SmallCustom',fontName='Helvetica',fontSize=8,leading=11,textColor=NAVY,spaceAfter=6))
S['Heading1'].textColor=NAVY;S['Heading1'].fontSize=18;S['Heading1'].leading=23;S['Heading1'].spaceAfter=12
S['Heading2'].textColor=TEAL;S['Heading2'].fontSize=12;S['Heading2'].spaceBefore=9;S['Heading2'].spaceAfter=7
def p(s,small=False):return Paragraph(s,S['SmallCustom' if small else 'BodyCustom'])
def heading(s):return Paragraph(s,S['Heading1'])
def h2(s):return Paragraph(s,S['Heading2'])
def table(headers,rows,widths=None):
 th=ParagraphStyle('th',parent=S['SmallCustom'],textColor=colors.white,fontName='Helvetica-Bold')
 t=Table([[Paragraph(html.escape(str(x)),th) for x in headers]]+[[p(html.escape(str(x)),True) for x in r] for r in rows],colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),NAVY),('TEXTCOLOR',(0,0),(-1,0),colors.white),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,LIGHT]),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,0),.5,TEAL)]))
 return t
def foot(c,doc):
 c.saveState();w,h=A4;c.setStrokeColor(colors.HexColor('#d9e4ed'));c.line(42,38,w-42,38);c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#64758a'));c.drawString(42,25,'SOUMABHA BHIM  /  CUSTOMER INTELLIGENCE');c.drawRightString(w-42,25,str(doc.page));c.restoreState()
def pdf(name,story):
 doc=SimpleDocTemplate(str(O/name),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=40,bottomMargin=49,title=name.replace('_',' ').replace('.pdf',''),author='Soumabha Bhim');doc.build(story,onFirstPage=foot,onLaterPages=foot)
def title(kicker,name,subtitle):return [Paragraph(kicker,S['Kicker']),Paragraph(name,S['TitleCustom']),p(subtitle),Spacer(1,8)]
def page(s,name):s.append(PageBreak());s.append(heading(name))
def money(x):return f'${x:,.0f}'
def pct(x):return f'{x:.1%}'

def report():
 s=title('STRATEGIC ANALYSIS / 01','Decoding Customer Value','A SQL-driven retention strategy for a US D2C fashion brand. Prepared by Soumabha Bhim from the supplied customer snapshot.')
 s += [table(['Customers','Recorded sales','Promo sales share','Repeat cadence proxy'],[['3,900','$233,081','42.65%','27.85%']],[128,128,128,127]),Spacer(1,16),h2('The decision'),p('The snapshot shows meaningful promotion exposure alongside an identifiable group of frequent, experienced customers. It does <b>not</b> demonstrate that promotions cause loyalty or that the business is dependent on discounts. Protect sales through a controlled offer-reduction pilot rather than a blanket withdrawal.'),h2('What the evidence supports'),p('<b>1.</b> 1,677 customers (43.0%) have a promo flag; their recorded purchases total $99,411. These sales are associated with a promotion, not proven incremental sales.'),p('<b>2.</b> Definition A identifies 1,086 customers with at least 26 previous purchases and stated cadence of at least monthly. Definition B identifies 817 with at least 26 previous purchases and a rating of at least 4.'),p('<b>3.</b> High annual-spend-proxy customers are 20.0% of the base but account for only 25.7% of recorded sales. The data does not show an 80/20 concentration of observed revenue.'),p('<b>4.</b> Arizona, Alaska and Tennessee lead a regularized, commercially screened geographic test shortlist. Acquisition efficiency remains unknown without market reach and CAC.'),p('<b>5.</b> Start with 74 satisfied, established, high-proxy-value promo-exposed customers. Their recorded sales are $5,356; use them for pilot feasibility, not a powered claim of sales safety.'),h2('Evidence boundary'),p('One row represents one customer and one recorded purchase. There are no timestamps, tenure duration, future outcomes, discount amounts, product costs or acquisition spend. All revenue figures refer to the supplied snapshot; no monthly or annual period can be assigned.')]
 page(s,'1 / Data preparation and quality')
 s += [table(['Audit','Result','Treatment'],[['Rows / customer IDs','3,900 / 3,900 unique','All rows retained; no duplicates'],['Review ratings','37 missing (0.95%)','Preserve missing; satisfaction = Unknown'],['Discount vs promo code','Identical in all rows','Use one exposure signal; avoid double counting'],['Frequency labels','7 raw / 5 normalized','Bi-Weekly + Fortnightly = 26/year; Quarterly + Every 3 Months = 4/year'],['Gender / offers','No female promo customers','No female treated overlap; avoid causal gender claims'],['Subscriptions','All 1,053 subscribers promo exposed','No untreated subscriber counterfactual'],['Previous purchases','Range 1-50','No observed first-time customers; no one-time-buyer inference']],[125,155,231]),Spacer(1,12),p('Clean field names to snake_case, trim text, validate Yes/No domains, check IDs and numeric ranges. No arbitrary outlier removal or review imputation is applied. The raw CSV is retained unchanged and SHA-256 fingerprinted.'),h2('Granularity governs interpretation'),p('State is available, but city and region are not. Previous purchases measure order history, not account tenure. Season is a category attached to the recorded purchase, not a dated seasonal time series. There is no valid RFM recency measure, churn model, two-year prediction or observed retention rate.'),h2('Selection and construction risks'),p('Gender, subscription and promotion overlap sharply. Their relationships may reflect data construction or business eligibility rules; provenance is not supplied. Gender is not recommended as an acquisition exclusion. Validate actual offer eligibility before operational targeting.')]
 page(s,'2 / Engineered features and decisions')
 rows=[['annual_orders_proxy','Weekly 52; two-weekly 26; monthly 12; quarterly 4; annual 1','Normalize stated cadence; plan contact frequency'],['dependency_score','100 x current promo flag (0 or 100)','Exposure screen only; historical dependency is unidentifiable'],['satisfaction_flag','Rating >=4 satisfied; <3.5 recovery; other known neutral; missing unknown','Protect dissatisfied / unknown customers from initial sunset'],['annual_spend_proxy_usd','Recorded amount x annual_orders_proxy','Value-tier prioritization; assumes stable order size and cadence'],['historical_value_proxy_usd','Recorded amount x (previous purchases + 1)','Rough history scale; not realized lifetime revenue'],['value_tier','High >=1924; Core >=572 and <1924; Developing <572','Fixed full-sample 80th / 50th percentile cutoffs'],['loyalty_a / loyalty_b','A: history >=26 and annual orders >=12; B: history >=26 and rating >=4','Competing definitions; A primary repeat-behavior proxy'],['history_band','0-10 / 11-25 / 26+ previous purchases','Compare category entry-like vs established mix'],['segment','Loyalty A yes/no x promo yes/no','Four traceable offer-treatment groups'],['sunset_eligible','Established promo exposed + High tier + rating >=4','Select controlled sunset pilot cohort']]
 s += [table(['Feature','Definition','Decision / limitation'],rows,[130,185,196]),Spacer(1,10),p('Age bands: 18-24, 25-34, 35-44, 45-54, 55-64, 65+. Other support fields: subscriber and satisfied binaries, high_history (26+), cadence_group, dependency_band, and value_tier_order. All definitions are implemented in src/pipeline.py and documented in the feature dictionary.',True)]
 page(s,'3 / Two loyalty definitions, tested')
 comp=M['loyalty_comparison']
 s += [table(['Test','A: history + cadence','B: history + satisfaction'],[['Selected customers',f"{comp[0]['customers']:,} (27.85%)",f"{comp[1]['customers']:,} (20.95%)"],['Selected AOV','$59.58','$61.30'],['Other-customer AOV','$59.84','$59.36'],['AOV difference','$-0.26','$1.94'],['95% bootstrap CI','$-1.97 to $1.38','$0.16 to $3.84'],['Mean annual spend proxy','$1,733.51','$1,082.31'],['Satisfied share','42.91%','100% by construction'],['Definition overlap','Jaccard = 32.43%','Different constructs; not interchangeable']],[165,173,173]),Spacer(1,12),h2('Primary choice: A, as an operational repeat-behavior proxy'),p('A requires both accumulated purchase experience and ongoing stated cadence. It captures repeat behavior more directly than B, which can include annual shoppers with a favorable rating. The cadence-history conjunction supplies a clear operational logic for replenishment and relationship marketing. This is a choice of measurement construct, not evidence of future predictive accuracy.'),p('Independent recorded spend does not validate A as a higher-ticket group: its AOV difference is near zero. B has a small exploratory positive difference, but satisfaction is 100% by definition and does not validate the label. Bootstrap intervals use 3,000 customer resamples per group, seed 42, assume independent customers, and are not adjusted for multiple comparisons.'),h2('Avoid circular validation'),p('The annual spend proxy multiplies frequency, which is also part of A. Higher proxy spend in A is partly mechanical and must not be presented as independent proof. Value tiers and A also share cadence; dashboard scatter relationships inherit that construction.'),h2('Robustness and future validation'),p('threshold_sensitivity.csv evaluates 12 combinations: history thresholds 20, 26, 30, 38 and annual-order thresholds 4, 12, 26. These are operational sensitivity checks, not model tuning. Validate either definition prospectively against 90/180-day repurchase, contribution and survival outcomes once dates exist.')]
 page(s,'4 / Value distribution and customer segments')
 v=pd.read_csv(P/'value_tiers.csv').sort_values('value_tier_order')
 s += [table(['Tier','Customers','Recorded sales','Sales share'],[[r.value_tier,f'{r.customers:,}',money(r.observed_sales_usd),pct(r.sales_share)] for r in v.itertuples()],[110,110,150,141]),Spacer(1,14)]
 seg=pd.read_csv(P/'segments.csv')
 s += [table(['Segment','Customers','Sales','Action'],[[r.segment,str(r.customers),money(r.observed_sales_usd),{'Established full price':'Maintain full-price relationship','Established promo exposed':'Test targeted offer reduction','Developing full price':'Improve second/next purchase journey','Developing promo exposed':'Test smaller first incentives; do not label bargain hunters'}[r.segment]] for r in seg.itertuples()],[145,65,95,206]),Spacer(1,12),Image(str(O/'figures/founder_dashboard.png'),width=511,height=322),p('The dashboard uses value tiers for the promo/loyalty scatter. Using the four loyalty x promo segments there would produce deterministic 0/1 coordinates and provide little analytical information.',True)]
 page(s,'5 / Promotions and margin economics')
 s += [p('<b>Observed exposure:</b> 43.0% of customers and 42.65% of recorded sales carry a promo flag. Discount amounts are missing, so actual discount cost, gross margin and incrementality cannot be calculated.'),p('Within male non-subscribers, the promo vs full-price AOV difference is $-1.06 (95% bootstrap CI $-3.49 to $1.42). Restriction improves overlap but does not remove selection bias or establish treatment effect. Female shoppers have no promo observations and subscribers have no full-price observations.'),h2('Illustrative full-removal scenario: eligible cohort only'),p('Assume the $5,356 recorded purchase total is net of a 15% discount, and COGS is 60% of list-price sales. These are planning assumptions, not facts in the dataset. The scenario rescales the cohort snapshot; it is not an annual profit forecast.'),table(['Volume loss','Scenario revenue','Gross profit','GP change'],[['0%','$6,301','$2,520','+$945'],['5%','$5,986','$2,394','+$819'],['10%','$5,671','$2,268','+$693'],['20%','$5,041','$2,016','+$441']],[105,140,130,136]),Spacer(1,12),p('Baseline illustrative gross profit is $1,575. At 20% volume loss gross profit still rises, but revenue falls by $315: margin and sales protection are different constraints. The revenue-preserving loss ceiling is 15%; the gross-profit break-even loss is 37.5% under these assumptions.'),h2('Transparent equations'),p('Let R = observed net sales; d = assumed discount; c = COGS/list sales; l = order-volume loss. List sales L = R/(1-d). Baseline GP = R-cL. Full-removal GP = (1-l)L(1-c). Revenue break-even loss = d. GP break-even loss = d/(1-c). Fixed costs, returns, shipping and offer-cost behavior are excluded.'),p('margin_scenarios.csv contains 36 combinations of discount (10/15/20%), COGS (40/60/75%) and loss (0/5/10/20%). Partial discount reduction requires net multiplier (1-d_new)/(1-d_old), not the full-removal formula. Obtain order-level discount and cost data before setting a business case.')]
 page(s,'6 / Category and season evidence')
 cat=pd.read_csv(P/'categories.csv')
 s += [table(['Category','Customers','High-history share','AOV','Promo share'],[[r.category,str(r.customers),pct(r.high_history_rate),f'${r.aov_usd:.2f}',pct(r.promo_rate)] for r in cat.itertuples()],[110,80,120,90,111]),Spacer(1,12),p('High-history shares are close: 48.8%-50.6%. Outerwear has the largest low-history share (23.1%, versus about 19.5%-20.0% elsewhere) and the lowest AOV ($57.17). Treat this as a merchandising test hypothesis, not proof that outerwear attracts one-time shoppers.'),h2('Seasonal mix'),p('High-history shares are Fall 47.6%, Spring 47.9%, Summer 51.9%, Winter 51.1%. These small cross-sectional differences do not establish a seasonal retention pattern. Exposure, category availability and customer mix are unobserved.'),h2('Answers to the category funnel request'),p('The four-panel dashboard compares each category across low (0-10), mid (11-25) and high (26+) purchase history. Because each customer has one item/category and history is total brand purchases, the chart does not show the first category bought, category-level repeat purchases or transitions. Entry-point and retention categories remain proxies.'),h2('Commercial action and trade-off'),p('Test outerwear follow-up recommendations after purchase and maintain broad clothing/accessory coverage. Compare personalized cross-sell with a no-message holdout. Track 90-day contribution per eligible customer, conversion, unsubscribe and returns. The risk is wasted contacts or unwanted bundles; do not shift inventory materially on these small descriptive gaps.'),p('All query outputs are included: category_funnel, season_patterns and q2_behavior. Revenue figures and proportions reconcile to the customer-level dataset.')]
 page(s,'7 / Geographic opportunity and demographics')
 g=pd.read_csv(P/'geography.csv').query('screen_qualified == 1').sort_values('opportunity_rank').head(8)
 s += [table(['State','n','AOV','Promo','Smoothed full-price $/customer'],[[r.state,str(r.customers),f'${r.aov_usd:.2f}',pct(r.promo_rate),f'${r.smoothed_full_price_spend_per_customer:.2f}'] for r in g.itertuples()],[110,45,75,75,206]),Spacer(1,12),p('Screen: at least 60 customers, AOV above $59.76, and promo customer share below 43%. Rank by (state full-price sales + 50 x national full-price sales/customer)/(state customers + 50). The 50-customer prior reduces sensitivity to small samples; it is a heuristic, not an estimated causal effect.'),p('Kansas ranks third on regularized full-price spend but fails the AOV screen, demonstrating why rank and commercial qualification are separate. Arizona, Alaska and Tennessee are the top qualified candidates; no state is proven underpenetrated without population, impressions, media spend and market share.'),h2('State-level targeting action'),p('Run matched-budget, randomized audience or geo tests in Arizona and Tennessee; use Alaska as a separate test because shipping economics could differ. Primary outcome: incremental contribution after CAC, returns and delivery cost. Trade-off: lower promo exposure may reflect customer selection, and remote shipping can eliminate a higher basket-value advantage.'),h2('Demographic boundaries'),p('Age has almost no linear association with recorded purchase amount (r=-0.010); previous purchase count has r=0.008 with purchase amount. Do not create a narrow age target based on weak aggregate signals. Preserve age/gender slices for descriptive monitoring, and use behavior and product affinity for acquisition tests.'),p('The SQL geographic and demographic views provide auditable candidate screens. They cannot estimate commercial underleveraging because market opportunity denominators are absent.')]
 page(s,'8 / Ideal customer profile and acquisition use')
 s += [p('<b>Operational seed:</b> value tier High, loyalty A=1, promo_exposed=0 and review_rating>=4. This yields 103 customers (2.64% of the base). These are satisfied, experienced, frequent customers with a full-price purchase observed; persistent full-price loyalty is not established.'),table(['Profile dimension','Evidence','How to use'],[['Cadence','55 weekly; 48 every two weeks','Choose replenishment reminders; frequency is partly selected by rule'],['Age','25-34: 24.3% vs 19.4% base','Test broad adjacent ages; no age exclusion'],['Category','Clothing 43.7%; footwear 23.3% vs 15.4% base','Test footwear creative and clothing cross-sell'],['Payment','Credit card 24.3% vs 17.2% base','Keep convenient checkout; preference is not a causal value driver'],['Satisfaction','All >=4 by cohort rule','Use service quality as a safeguard, not external validation'],['Gender','Female 54.4% vs 32.0% base','Do not target/exclude by this: promo overlap mechanically biases the seed']],[110,185,216]),Spacer(1,12),h2('Acquisition brief'),p('Reach shoppers with demonstrated apparel/footwear interest using full-price product-quality creative, fit guidance and convenient checkout. Test modeled audiences based on the seed only where consent and platform policy allow; exclude current customers from prospecting evaluation. Compare with broad-interest acquisition using equal budgets and a holdout.'),h2('Success and trade-off'),p('Track incremental contribution per acquired customer, new-customer CAC, 90-day repeat purchase and return rate. Risk: a small, mechanically selected seed can overfit and exclude good occasional shoppers. Keep 20% of test budget for broad exploration; do not project seed frequency into future CLV.'),h2('What the ideal profile is not'),p('It is not proof that a particular age, state, payment method or gender causes loyalty. Rankings from a 103-customer seed are descriptive. Per-level counts, shares and population indices are supplied in icp_profile.csv.')]
 page(s,'9 / Reproduction, verification and next data')
 s += [h2('Reproducible deliverables'),p('Python: raw data, cleaned/engineered CSV, all summary outputs, reproducible scripts and an executable notebook. SQL: nine views plus a populated SQLite database. Power BI: four-panel PBIP project with embedded source data, model, report definitions, DAX measures and theme. A standalone offline HTML companion provides filters, a schematic state map and CSV export.'),h2('Verification performed'),p('Validated 3,900 unique customer rows, domains and ranges; preserved 37 unknown ratings; reconciled SQL customer counts and recorded sales; verified loyalty rules and embedded Power BI data against CSV; generated all SQL outputs and deterministic bootstrap results. PDFs are rendered for visual checks. Power BI Desktop runtime validation is separate from source/schema checks; see powerbi/OPEN_IN_POWER_BI.md for status and steps.'),h2('Minimum data contract for genuine retention'),table(['Required field / table','Decision unlocked'],[['Order ID, customer ID, order timestamp, signup date','Cohorts, recency, tenure and future repurchase'],['List price, net price, discount amount, offer ID','Actual discount depth and promotional cost'],['Randomized offer assignment and exposure log','Incremental effect and discount response'],['SKU-level order lines, returns, COGS, fulfillment cost','Category transitions and contribution margin'],['Acquisition source, campaign spend, exposure, geography','Incremental CAC and geographic opportunity'],['Consent, communications, service contacts','Responsible targeting and service recovery']],[255,256]),Spacer(1,10),h2('Sources and provenance'),p('Business requirements: supplied Problem Statements1.pdf, three pages. Analysis source: supplied Dataset.csv, 3,900 rows and 18 fields. No external customer data has been substituted. Microsoft documentation was used only for the Power BI file format, not for business findings.',True),p('Power BI format references: https://learn.microsoft.com/en-us/power-bi/developer/projects/projects-report ; https://learn.microsoft.com/en-us/power-bi/developer/projects/projects-dataset . Raw-data SHA-256 is recorded in data/processed/metrics.json.',True)]
 pdf('Customer_Intelligence_Report.pdf',s)

def playbook():
 s=title('ACTION PLAYBOOK / 02','Retention & Promotional Sunset','Named cohorts, measurable triggers, a staged rollout and explicit commercial trade-offs.')
 s += [h2('Pilot: established promo-exposed, satisfied high-value-proxy customers'),p('<b>Exact trigger:</b> previous_purchases>=26; annual_orders_proxy>=12; annual_spend_proxy_usd>=1924; current promo flag=1; review_rating>=4. All conditions must hold. Current cohort: 74 customers; recorded cohort sales: $5,356. Current promo use alone does not identify dependency.'),table(['When / owner','Action','Gate / trade-off'],[['Weeks 0-2 / CRM + data','Verify eligibility and current offer depth; log random assignment, offer exposure, net sales, costs, returns and dates. Freeze the cohort.','No live reduction without baseline offer/cost data. Risk: delayed launch; benefit: measurable economics.'],['Weeks 3-6 / CRM','Randomly split 37/37: control retains current eligible offer; treatment reduces discount by 5 percentage points (e.g., 15% to 10%). Honor existing entitlements.','Keep assignment persistent, stratify by cadence and tier value. Risk: short-term volume loss / offer dissatisfaction.'],['Weeks 7-12 / analytics','Keep randomized groups; monitor contribution/customer and 90-day revenue/customer, conversion, returns and complaints.','Use the 74-customer pilot for feasibility. Do not call a nonsignificant result safe.'],['Week 13+ / growth + finance','Accrue newly eligible customers under the same rules; reduce another 5 points only when the agreed evidence gate passes. Repeat until zero discount.','Retain a holdout. Pause or revert if revenue/customer breaches the 5% business guardrail or service metrics deteriorate.']],[115,205,191]),Spacer(1,10),p('<b>Primary outcome:</b> 90-day contribution per randomized eligible customer, including non-buyers as zero, net of returns, COGS, variable fulfillment and discount. Co-primary sales guardrail: revenue per eligible customer; never compare only converters. Track both intent-to-treat effects and confidence intervals.',True)]
 page(s,'Economics, power and segment treatment')
 s += [h2('Evidence gate and honest power'),p('For expansion, pre-register a one-sided revenue non-inferiority margin of -5% and require its 95% lower confidence bound above that margin, alongside positive contribution evidence. Estimate the necessary sample from measured revenue variance; this dataset has no 90-day outcome variance. A diagnostic 30% repurchase baseline and 10-percentage-point detectable difference require about 330 customers per arm (two-sided 5%, 80% power). This is illustrative and does not power the revenue guardrail.'),p('With only 37 per arm, the pilot can detect only very large differences (roughly 30 percentage points in that binary example). It cannot demonstrate that a 5% revenue loss is excluded. Newly eligible customers must accrue prospectively; do not broaden the cohort after seeing results just to obtain significance.'),h2('Margin illustration and trade-off'),p('At assumed 15% baseline discount and 60% COGS/list value, full removal across the current cohort at unchanged volume yields +$945 illustrative gross profit. With 10% volume loss it yields +$693 GP and +$315 revenue; with 20% volume loss it yields +$441 GP but -$315 revenue. No result is an actual measured saving. Full removal differs from the initial 5-point test.'),table(['Segment / trigger','Offer strategy','Risk / tracking'],[['Established full price: A=1, promo=0','Maintain product/service benefits; do not introduce an automatic cash discount.','Missed conversion opportunities; monitor repeat purchases and contribution with holdout.'],['Established promo exposed: A=1, promo=1','Only satisfied High-tier customers enter initial sunset pilot; other customers remain under observation.','Offer removal may reduce orders; randomized guardrails determine scale.'],['Developing full price: A=0, promo=0','Test fit guidance, relevant cross-sell and reminders before incentives.','Extra messages may annoy; track conversion, unsubscribes and incremental contribution.'],['Developing promo exposed: A=0, promo=1','Test targeted, smaller incentives versus current offer; do not call them one-time bargain hunters.','Discount leakage and lower volume; track incremental contribution, not redemption alone.']],[152,183,176])]
 page(s,'Ideal customer profile and acquisition brief')
 s += [p('<b>Seed definition:</b> High value tier + loyalty A + satisfied + current full-price observation. Size: 103 customers. Weekly/two-weekly shoppers with 26+ past orders, strong recorded order size/cadence proxy and rating>=4 are the operational target.'),table(['Signal','What the sample says','Marketing action / risk'],[['Category','Clothing 45/103; footwear 24/103','Test quality-led footwear creative and clothing cross-sell; category-level future value is unproven.'],['Age','25-34 is 25/103; 45-54 is 22/103','Keep broad adult targeting; small differences can overfit.'],['Payments','Credit card 25/103; bank transfer 20/103','Reduce checkout friction across methods; do not gate acquisition on payment.'],['Geography','Screen leaders: Arizona, Alaska, Tennessee','Start matched-spend tests in Arizona/Tennessee; separate Alaska shipping economics.'],['Gender','56 female, 47 male','Avoid gender exclusions; the full-price rule interacts with the zero-promo female data.']],[95,180,236]),Spacer(1,12),h2('Next 90 days'),p('CRM owns persistent customer assignment and eligibility. Finance supplies net revenue, COGS, returns and fulfillment cost. Analytics publishes weekly intent-to-treat outcomes with intervals and checks assignment balance; growth owns equally budgeted creative/geo tests. The founder approves scale only after the pre-agreed evidence gate.'),h2('Acquisition experiment'),p('Compare a behavior/category-led seed audience against broad interest, with equal budgets and holdout measurement. Use full-price product, fit and quality messages. Evaluate new-customer CAC plus 90-day contribution after returns, not clicks or first-order AOV. Allocate 20% of test budget to broad discovery to reduce overfitting. Risk: seed shoppers may be expensive to reach and less representative than the broad market.'),h2('When either strategic scenario is confirmed'),p('If prospective controlled tests show full-price repurchase and contribution are preserved, expand the sunset in stages while monitoring sales. If removing discounts reduces contribution or breaches the revenue guardrail, retain targeted offers and invest in service/product value; investigate which customers and categories exhibit a measured incremental response. Neither scenario is established by the current snapshot.')]
 pdf('Retention_Playbook.pdf',s)

def executive():
 s=title('EXECUTIVE SUMMARY / ONE PAGE','Build loyalty evidence.<br/>Test discount reduction.','D2C customer intelligence | Soumabha Bhim')
 s += [table(['Snapshot','Finding'],[['3,900 customers','$233,081 recorded sales; no reporting period available'],['Promotion exposure','43.0% of customers; 42.65% of recorded sales'],['Repeat cadence proxy','1,086 customers (27.85%): 26+ previous purchases and at least monthly cadence'],['High proxy-value tier','781 customers (20.03%); 25.69% of recorded sales']],[145,366]),Spacer(1,11),h2('What founders should conclude'),p('The business has customers with substantial purchase history, but this snapshot cannot establish retention, two-year value or causal discount dependency. Promo and discount flags are identical. All subscribers and all discounted customers are male, making simple segment comparisons confounded.'),h2('Three actions'),p('<b>1. Run a controlled sunset pilot.</b> Start with 74 satisfied, established, high-value-proxy promo-exposed customers. After instrumentation, test a 5-percentage-point discount reduction against unchanged offers. Track 90-day contribution and revenue per randomized customer. The cohort is too small to establish sales safety; accrue a powered follow-up before expansion.'),p('<b>2. Test full-price geographic demand.</b> Arizona, Alaska and Tennessee lead the qualified state screen for high spend and low promo exposure. Prioritize small matched-budget tests in Arizona/Tennessee; evaluate Alaska shipping costs separately. Market penetration and incremental CAC are unknown.'),p('<b>3. Acquire on behavior and product affinity.</b> The 103-customer ICP seed combines High tier, frequent accumulated purchasing, satisfaction and a current full-price purchase. Test apparel/footwear quality creative and convenient checkout. Avoid gender exclusions and narrow age targeting.'),h2('Economic upside is conditional'),p('Assuming a 15% discount and COGS of 60% of list price, full removal in the 74-customer cohort implies +$945 illustrative gross profit at unchanged volume, or +$693 with 10% volume loss. These are scenarios, not measured or annual savings. Revenue would fall if volume loss exceeded 15%.'),p('<b>Next data:</b> dated order history, actual discount amounts, offer assignment, costs, returns and acquisition spend. Validate loyalty definitions prospectively. Do not use this snapshot to promise future retention.',True)]
 pdf('Executive_Summary.pdf',s)
def main():report();playbook();executive();print('Three PDF deliverables generated')
if __name__=='__main__':main()
